import { parentingNarrative } from "./ugc-parenting";

export const detailedParentingNarrative = `Direction: conserver un regard bienveillant et une posture ouverte, sans jouer une transformation ni un avant-après. La conversation reste crédible, avec des hésitations naturelles et des silences courts. Le salon est sobre; le canapé et une fenêtre suffisent au décor. La lumière du jour éclaire les visages de côté sans effet dramatique. Le téléphone reste un accessoire réel montrant uniquement la couverture fournie. Les personnages ne regardent pas constamment la caméra et ne récitent pas les faits comme un argumentaire commercial. Aucun objet ne symbolise de résultat acquis. Les gestes doivent correspondre à la phrase entendue, sans accélérer les mouvements ni ajouter de démonstration qui ne soit pas décrite.\n${parentingNarrative}`;
